[[noreturn]] void py_throw(const char* type, const std::string& msg) {
    std::string t = type;
    if (t == "KeyError") { auto k = std::make_shared<KeyError>(msg); k->a_repr[0] = msg; throw PyThrow{k}; }  // msg est déjà un repr de clé
    if (t == "Exception") throw PyThrow{std::make_shared<Exception>(msg)};
    if (t == "ArithmeticError") throw PyThrow{std::make_shared<ArithmeticError>(msg)};
    if (t == "ZeroDivisionError") throw PyThrow{std::make_shared<ZeroDivisionError>(msg)};
    if (t == "OverflowError") throw PyThrow{std::make_shared<OverflowError>(msg)};
    if (t == "LookupError") throw PyThrow{std::make_shared<LookupError>(msg)};
    if (t == "IndexError") throw PyThrow{std::make_shared<IndexError>(msg)};
    if (t == "KeyError") throw PyThrow{std::make_shared<KeyError>(msg)};
    if (t == "ValueError") throw PyThrow{std::make_shared<ValueError>(msg)};
    if (t == "TypeError") throw PyThrow{std::make_shared<TypeError>(msg)};
    if (t == "AttributeError") throw PyThrow{std::make_shared<AttributeError>(msg)};
    if (t == "NameError") throw PyThrow{std::make_shared<NameError>(msg)};
    if (t == "EOFError") throw PyThrow{std::make_shared<EOFError>(msg)};
    if (t == "StopIteration") throw PyThrow{std::make_shared<StopIteration>(msg)};
    if (t == "AssertionError") throw PyThrow{std::make_shared<AssertionError>(msg)};
    if (t == "RuntimeError") throw PyThrow{std::make_shared<RuntimeError>(msg)};
    if (t == "NotImplementedError") throw PyThrow{std::make_shared<NotImplementedError>(msg)};
    if (t == "RecursionError") throw PyThrow{std::make_shared<RecursionError>(msg)};
    throw PyThrow{std::make_shared<RuntimeError>(msg)};
}
template <class T> [[noreturn]] static inline void py_raise(const std::shared_ptr<T>& e) {
    if (!e) py_throw("TypeError", "exceptions must derive from BaseException");
    throw PyThrow{e};
}
template <class T> std::string py_repr_any(const T& x) { return py_repr(x); }
template <class T> static inline bool py_isinst(const PyThrow& t) { return std::dynamic_pointer_cast<T>(t.p) != nullptr; }
struct PyFinally {  // `finally` : s'exécute à toute sortie du bloc try (fin normale, return, break, continue, exception)
    std::function<void()> f;
    explicit PyFinally(std::function<void()> g) : f(std::move(g)) {}
    ~PyFinally() noexcept(false) { f(); }
};
